import React from "react";
import "./../../css/service-detail.css";

import SpecialistsSection from "./SpecialistsSectionComponent";
import ReviewsSection from "./ClientReviewsComponent";
import FaqSection from "./FAQComponent";
import RelatedServicesSection from "./RelatedServicesComponent";

class ServiceDetail extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      service: null,
      loading: true,
      error: null,

      liked: false,
      activeTab: "before",
      openFaq: 0,
    };
  }

  componentDidMount() {
    this.fetchService();
  }

  fetchService = async () => {
    try {
      this.setState({
        loading: true,
        error: null,
      });

      const id = window.location.pathname
        .split("/")
        .filter(Boolean)
        .pop();

      if (!id) {
        throw new Error("شناسه خدمت مشخص نیست.");
      }

      const response = await fetch(
        `http://127.0.0.1:8000/api/services/${id}`
      );

      if (!response.ok) {
        throw new Error(
          "دریافت اطلاعات خدمت با خطا مواجه شد."
        );
      }

      const result = await response.json();

      if (!result.success) {
        throw new Error(
          result.message || "دریافت خدمت ناموفق بود."
        );
      }

      this.setState({
        service: result.data,
        loading: false,
      });
    } catch (error) {
      console.error("Service Detail Error:", error);

      this.setState({
        loading: false,
        error:
          error.message ||
          "خطا در دریافت اطلاعات خدمت.",
      });
    }
  };

  handleBack = () => {
    if (this.props.navigate) {
      this.props.navigate("/services");
      return;
    }

    window.history.back();
  };

  handleLike = () => {
    this.setState((prevState) => ({
      liked: !prevState.liked,
    }));
  };

  handleTabChange = (tab) => {
    this.setState({
      activeTab: tab,
    });
  };

  handleFaq = (index) => {
    this.setState((prevState) => ({
      openFaq:
        prevState.openFaq === index ? null : index,
    }));
  };

  handleViewProfile = (specialist) => {
    console.log("Specialist:", specialist);
  };

  handleShare = async () => {
    const { service } = this.state;

    if (!service) {
      return;
    }

    try {
      if (navigator.share) {
        await navigator.share({
          title: service.name,
          text: service.short_description || service.name,
          url: window.location.href,
        });
      } else {
        await navigator.clipboard.writeText(
          window.location.href
        );

        alert("لینک خدمت کپی شد.");
      }
    } catch (error) {
      console.log("Share cancelled.");
    }
  };

  renderStars = () => {
    return (
      <span className="detail-stars">
        {[1, 2, 3, 4, 5].map((star) => (
          <svg
            key={star}
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="currentColor"
          >
            <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z" />
          </svg>
        ))}
      </span>
    );
  };

  formatNumber = (value) => {
    if (
      value === null ||
      value === undefined ||
      value === ""
    ) {
      return "—";
    }

    return Number(value).toLocaleString("fa-IR");
  };

  formatRating = (value) => {
    if (
      value === null ||
      value === undefined
    ) {
      return "—";
    }

    return Number(value).toLocaleString("fa-IR", {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1,
    });
  };

  renderLoading = () => {
    return (
      <div className="service-detail-loading">
        در حال دریافت اطلاعات خدمت...
      </div>
    );
  };

  renderError = () => {
    const { error } = this.state;

    return (
      <div className="service-detail-error">
        <p>{error}</p>

        <button
          type="button"
          onClick={this.fetchService}
        >
          تلاش مجدد
        </button>
      </div>
    );
  };

  render() {
    const {
      service,
      loading,
      error,
      liked,
      activeTab,
      openFaq,
    } = this.state;

    if (loading) {
      return this.renderLoading();
    }

    if (error) {
      return this.renderError();
    }

    if (!service) {
      return (
        <div className="service-detail-error">
          خدمت موردنظر پیدا نشد.
        </div>
      );
    }

    const rating = this.formatRating(
      service.rating
    );

    const reviews = this.formatNumber(
      service.reviews
    );

    const price = this.formatNumber(
      service.price
    );

    const duration = this.formatNumber(
      service.duration_minutes
    );

    const tabs = {
      before: [
        "قبل از درمان، پوست خود را با شوینده ملایم تمیز کنید.",
        "حداقل ۲۴ ساعت قبل از درمان از لایه‌بردارهای قوی استفاده نکنید.",
        "در صورت داشتن حساسیت پوستی، قبل از درمان با متخصص مشورت کنید.",
      ],

      during: [
        "در ابتدا پوست پاکسازی و برای درمان آماده می‌شود.",
        "ناخالصی‌ها و آلودگی‌های سطح پوست با دستگاه مخصوص استخراج می‌شوند.",
        "در مرحله پایانی سرم‌های متناسب با نوع پوست استفاده می‌شوند.",
      ],

      after: [
        "ممکن است قرمزی خفیف و موقتی داشته باشید.",
        "تا ۲۴ ساعت از سونا و ورزش سنگین خودداری کنید.",
        "برای محافظت از پوست از ضدآفتاب مناسب استفاده کنید.",
      ],
    };

    return (
      <>
        {/* Header */}

        <header className="page-header">
          <button
            className="icon-btn"
            aria-label="بازگشت"
            onClick={this.handleBack}
          >
            <svg
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="m15 18-6-6 6-6" />
            </svg>
          </button>

          <h1 className="page-title">
            {service.name}
          </h1>

          <div className="head-actions">

            {/* Like */}

            <button
              className={`icon-btn ${
                liked ? "liked" : ""
              }`}
              id="likeBtn"
              aria-label="علاقه‌مندی"
              onClick={this.handleLike}
            >
              <svg
                width="17"
                height="17"
                viewBox="0 0 24 24"
                fill={
                  liked
                    ? "currentColor"
                    : "none"
                }
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.6l-1-1a5.5 5.5 0 0 0-7.8 7.8l1 1L12 21l7.8-7.8 1-1a5.5 5.5 0 0 0 0-7.6z" />
              </svg>
            </button>

            {/* Share */}

            <button
              className="icon-btn"
              aria-label="اشتراک‌گذاری"
              onClick={this.handleShare}
            >
              <svg
                width="17"
                height="17"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <circle
                  cx="18"
                  cy="5"
                  r="3"
                />
                <circle
                  cx="6"
                  cy="12"
                  r="3"
                />
                <circle
                  cx="18"
                  cy="19"
                  r="3"
                />
                <path d="m8.6 13.5 6.8 3.9M15.4 6.6 8.6 10.5" />
              </svg>
            </button>

          </div>
        </header>

        {/* Scroll Area */}

        <div className="scroll-area">

          {/* Hero */}

          <div className="detail-hero">
            <div className="detail-hero-bg"></div>

            <div className="detail-hero-swirl">
              <svg
                width="120"
                height="120"
                viewBox="0 0 120 120"
                fill="none"
                opacity=".85"
              >
                <path
                  d="M60 15c24 0 45 21 45 45s-21 45-45 45S15 84 15 60"
                  stroke="#fff"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeDasharray="4 8"
                />

                <path
                  d="M60 30c17 0 30 13 30 30S77 90 60 90"
                  stroke="#fff"
                  strokeWidth="2"
                  strokeLinecap="round"
                />

                <circle
                  cx="60"
                  cy="60"
                  r="9"
                  fill="#fff"
                  fillOpacity=".9"
                />
              </svg>
            </div>

            <div className="hero-badge-rate">
              <svg
                width="13"
                height="13"
                viewBox="0 0 24 24"
                fill="currentColor"
              >
                <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z" />
              </svg>

              {rating} · {reviews} نظر
            </div>

            <div className="hero-badge-price">
              از {price} تومان
            </div>
          </div>

          {/* Body */}

          <div className="detail-body">

            {/* Title */}

            <h2 className="detail-title">
              {service.name}
            </h2>

            <p className="detail-desc">
              {service.short_description}
            </p>

            {/* Rating */}

            <div className="detail-rate-row">
              {this.renderStars()}

              <span className="detail-rn">
                {rating}
              </span>

              <span>
                ({reviews} نظر)
              </span>

              <span className="detail-sep">
                ·
              </span>

              <span className="detail-dur-inline">

                <svg
                  width="13"
                  height="13"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle
                    cx="12"
                    cy="12"
                    r="10"
                  />

                  <path d="M12 6v6l4 2" />
                </svg>

                {duration} دقیقه

              </span>
            </div>

            {/* CTA */}

            <div className="cta-row">
              <button className="btn-outline">
                دریافت مشاوره
              </button>

              <button className="btn-solid">
                رزرو نوبت
              </button>
            </div>

            {/* Info Grid */}

            <div className="info-grid">

              <div className="info-box">
                <span className="info-ic">
                  <svg
                    width="17"
                    height="17"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <circle
                      cx="12"
                      cy="12"
                      r="10"
                    />

                    <path d="M12 6v6l4 2" />
                  </svg>
                </span>

                <div>
                  <div className="info-l">
                    مدت‌زمان
                  </div>

                  <div className="info-v">
                    {duration} دقیقه
                  </div>
                </div>
              </div>

              <div className="info-box">
                <span className="info-ic">
                  <svg
                    width="17"
                    height="17"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="m12 2 9 5-9 5-9-5 9-5Z" />
                    <path d="m3 12 9 5 9-5" />
                  </svg>
                </span>

                <div>
                  <div className="info-l">
                    قیمت
                  </div>

                  <div className="info-v">
                    {price} تومان
                  </div>
                </div>
              </div>

              <div className="info-box">
                <span className="info-ic">
                  <svg
                    width="17"
                    height="17"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M12 2 4 5v6c0 5 3.5 9 8 11 4.5-2 8-6 8-11V5l-8-3Z" />
                    <path d="m9 12 2 2 4-4" />
                  </svg>
                </span>

                <div>
                  <div className="info-l">
                    وضعیت
                  </div>

                  <div className="info-v">
                    {service.is_active
                      ? "فعال"
                      : "غیرفعال"}
                  </div>
                </div>
              </div>

              <div className="info-box">
                <span className="info-ic">
                  <svg
                    width="17"
                    height="17"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
                    <circle
                      cx="9"
                      cy="7"
                      r="4"
                    />

                    <path d="M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" />
                  </svg>
                </span>

                <div>
                  <div className="info-l">
                    متخصصین
                  </div>

                  <div className="info-v">
                    {this.formatNumber(
                      service.staff?.length || 0
                    )}
                  </div>
                </div>
              </div>

            </div>

            {/* Article */}

            {service.article_content && (
              <>
                <div className="detail-divider"></div>

                <h3 className="detail-h2">
                  درباره این خدمت
                </h3>

                <div
                  className="detail-desc"
                  dangerouslySetInnerHTML={{
                    __html:
                      service.article_content,
                  }}
                />
              </>
            )}

            {/* SEO Content */}

            {service.seo_content && (
              <>
                <div className="detail-divider"></div>

                <h3 className="detail-h2">
                  اطلاعات بیشتر
                </h3>

                <div
                  className="detail-desc"
                  dangerouslySetInnerHTML={{
                    __html:
                      service.seo_content,
                  }}
                />
              </>
            )}

            {/* Expectations */}

            <div className="detail-divider"></div>

            <h3 className="detail-h2">
              چه انتظاری باید داشته باشید؟
            </h3>

            <div className="wte-tabs">

              <button
                className={`wte-tab ${
                  activeTab === "before"
                    ? "active"
                    : ""
                }`}
                onClick={() =>
                  this.handleTabChange(
                    "before"
                  )
                }
              >
                قبل از درمان
              </button>

              <button
                className={`wte-tab ${
                  activeTab === "during"
                    ? "active"
                    : ""
                }`}
                onClick={() =>
                  this.handleTabChange(
                    "during"
                  )
                }
              >
                حین درمان
              </button>

              <button
                className={`wte-tab ${
                  activeTab === "after"
                    ? "active"
                    : ""
                }`}
                onClick={() =>
                  this.handleTabChange(
                    "after"
                  )
                }
              >
                بعد از درمان
              </button>

            </div>

            <div className="wte-list">

              {tabs[activeTab].map(
                (item, index) => (
                  <div
                    className="suit-item"
                    key={index}
                  >
                    <span className="suit-ic good">
                      <svg
                        width="18"
                        height="18"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      >
                        <circle
                          cx="12"
                          cy="12"
                          r="10"
                        />

                        <path d="m9 12 2 2 4-4" />
                      </svg>
                    </span>

                    {item}
                  </div>
                )
              )}

            </div>

            {/* Specialists */}

            <SpecialistsSection
              specialists={service.staff || []}
              onViewProfile={
                this.handleViewProfile
              }
            />

            {/* Reviews */}

            <ReviewsSection
              service={service}
            />

            {/* FAQ */}

            <FaqSection
              service={service}
              openFaq={openFaq}
              handleFaq={this.handleFaq}
            />

            {/* Related Services */}

            <RelatedServicesSection
              service={service}
            />

            {/* Not Sure */}

            <div className="notsure-card">

              <div className="notsure-ic">
                <svg
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
                </svg>
              </div>

              <div className="notsure-t">
                هنوز مطمئن نیستید؟
              </div>

              <p className="notsure-s">
                قبل از تصمیم‌گیری با یک متخصص
                صحبت کنید. بدون هیچ تعهدی.
              </p>

              <div className="notsure-btns">

                <button className="btn-solid">
                  دریافت مشاوره
                </button>

                <button className="btn-outline">
                  رزرو نوبت
                </button>

              </div>
            </div>

          </div>
        </div>

        {/* Sticky CTA */}

        <div className="sticky-cta">

          <button className="btn-outline">
            دریافت مشاوره
          </button>

          <button className="btn-solid">
            رزرو نوبت
          </button>

        </div>
      </>
    );
  }
}

export default ServiceDetail;
